        if(state==17 && ticks==25){require(mc.currentScreen instanceof GuiLargeCanopy,"three-wide settings open");CanopySliderRuntimeChecks.check(mc,(GuiLargeCanopy)mc.currentScreen);state=18;ticks=0;return false;}
        if(state==18 && ticks==30){pending=mc.getIntegratedServer().addScheduledTask(()->{TileEntityCanopy tile=TileEntityCanopy.at(mc.getIntegratedServer().getWorld(0),POS);require(tile.large.depth==80 && tile.large.scale==40,"three-wide drag final settings reached server");});state=19;return false;}
