        if(state==22 && ticks==30){CanopyOpacityRuntimeChecks.prepared(mc,1);shot(mc,output,"front_canopy_material_opacity");camera(mc,70.5,25,54,new Vec3d(70.5,22.5,68.5));state=23;ticks=0;return false;}
